def parse_duration(s):
    if not s:
        return None

    units = {'s': 1, 'm': 60, 'h': 3600}
    parts = s.replace(' ', '').split(' ')
    total = 0

    for part in parts:
        num, unit = part[:-1], part[-1]
        if unit in units:
            total += int(num) * units[unit]
        else:
            return None

    return total
